        wl = w - 2.5
        pl = 2.81022636e-08
        pl = 3.43273939e-07 + pl * wl
        pl = -3.5233877e-06 + pl * wl
        pl = -4.39150654e-06 + pl * wl
        pl = 2.1858087e-04 + pl * wl
        pl = -1.25372503e-03 + pl * wl
        pl = -4.17768164e-03 + pl * wl
